package com.example.eac_backend_project.transport;

import com.example.eac_backend_project.entity.transport.*;
import com.example.eac_backend_project.repository.transport.*;
import org.springframework.stereotype.Service;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.transaction.annotation.Transactional;
import java.util.*;
import java.time.*;
import java.math.*;
import static com.example.eac_backend_project.transport.TransportValues.*;
import static com.example.eac_backend_project.transport.TransportAccess.fail;

@Service @Transactional(readOnly=true)
public class TransportReportService {
 static final Map<String,String> TYPES;
 static {var types=new LinkedHashMap<String,String>();types.put("VEHICLE_REGISTER","Vehicle register");types.put("DRIVER_ASSIGNMENTS","Current driver assignments");types.put("FUEL_CONSUMPTION","Fuel consumption");types.put("FUEL_EXPENDITURE","Fuel expenditure");types.put("PREVENTIVE_MAINTENANCE","Preventive maintenance");types.put("CORRECTIVE_MAINTENANCE","Corrective maintenance");types.put("ROUTINE_MAINTENANCE","Routine inspection history");types.put("MAINTENANCE_COST","Maintenance cost");types.put("DOWNTIME","Recorded downtime");types.put("COMPONENT_REPLACEMENTS","Component replacements");types.put("DOCUMENT_EXPIRY","Vehicle document expiry");types.put("FAULTS","Fault reports");types.put("PROCUREMENT","Procurement requests");types.put("FORECASTS","Maintenance forecasts");types.put("OPERATING_COST","Vehicle operating cost");TYPES=Collections.unmodifiableMap(types);}
 @Autowired TransportAccess access;
 @Autowired TransportCoreService core;
 @Autowired VehicleRepository vehicles;
 @Autowired FuelRepository fuel;
 @Autowired MaintenanaceRepository maintenance;
 @Autowired TransportVehicleProfiles profiles;
 @Autowired TransportFuelDetails fuelDetails;
 @Autowired TransportMaintenanceDetails maintenanceDetails;
 @Autowired TransportWorkflows workflows;
 @Autowired TransportProcurementService procurement;
 @Autowired TransportTimelines timeline;
 @Autowired TransportPartReceipts partReceipts;
 @Autowired com.fasterxml.jackson.databind.ObjectMapper json;
 public Object types(){access.require("TRANSPORT_REPORTS");return TYPES.entrySet().stream().map(e->map("value",e.getKey(),"label",e.getValue())).toList();}
 private Vehicles fuelVehicle(Fuel entry){try{var v=core.fuelVehicle(entry);access.vehicle(v);return v;}catch(org.springframework.web.server.ResponseStatusException error){return null;}} private Vehicles maintenanceVehicle(Maintenance entry){try{var v=core.maintenanceVehicle(entry);access.vehicle(v);return v;}catch(org.springframework.web.server.ResponseStatusException error){return null;}}
 private Map<String,Object> base(Vehicles v,LocalDate date){var p=profiles.findByVehicle_Id(v.getId());return map("vehicleId",v.getId(),"registration",v.getDvla(),"vehicle",v.getName(),"vehicleType",v.getType(),"vehicleArchived",v.getArchivedAt()!=null,"department",p.map(x->x.department).orElse(null),"project",p.map(x->x.project).orElse(null),"date",date);}
 private Vehicles resolve(String reference){try{return core.resolveVehicle(reference);}catch(org.springframework.web.server.ResponseStatusException e){return null;}}
 private void vehicleFields(Map<String,Object> row,Vehicles v){row.putAll(base(v,null));var p=profiles.findByVehicle_Id(v.getId());row.put("driverId",p.filter(x->x.driver!=null).map(x->x.driver.getId()).orElse(null));row.put("driver",p.filter(x->x.driver!=null).map(x->x.driver.getDriverName()).orElse(null));}
 public Map<String,Object> report(String type,Map<String,String> filters){access.require("TRANSPORT_REPORTS");if(!TYPES.containsKey(type))throw fail(400,"Choose an available Transport report");LocalDate from=parseDate(filters.get("from")),to=parseDate(filters.get("to"));if(from!=null&&to!=null&&to.isBefore(from))throw fail(400,"End date must not precede start date");List<Map<String,Object>> rows=new ArrayList<>();var fleet=access.visible(vehicles.findAll());
  switch(type){
   case "VEHICLE_REGISTER","DRIVER_ASSIGNMENTS"->{for(var v:fleet){var r=base(v,null);vehicleFields(r,v);var p=profiles.findByVehicle_Id(v.getId());r.putAll(map("make",p.map(x->x.make).orElse(null),"model",p.map(x->x.model).orElse(null),"year",v.getYear(),"vin",v.getVin(),"status",v.getArchivedAt()!=null?"ARCHIVED":p.map(x->x.operationalStatus).orElse(v.getStatus()),"currentMileage",v.getCurrentMileage(),"acquisitionDate",p.map(x->x.acquisitionDate).orElse(null)));r.put("date",p.map(x->x.acquisitionDate).orElse(null));if(!type.equals("DRIVER_ASSIGNMENTS")||r.get("driverId")!=null)rows.add(r);}}
   case "FUEL_CONSUMPTION","FUEL_EXPENDITURE"->{for(var f:fuel.findAll()){if(f.getArchivedAt()!=null)continue;var v=fuelVehicle(f);var r=v==null?map("vehicleId",null,"registration",f.getVehicle(),"vehicle","Unmatched legacy reference","date",f.getDate()):base(v,f.getDate());var detail=fuelDetails.findByFuel_Id(f.getId());r.putAll(map("id",f.getId(),"driver",f.getDriver(),"driverId",detail.filter(d->d.driver!=null).map(d->d.driver.getId()).orElse(null),"litres",f.getLitres(),"costGhs",f.getCost(),"odometer",f.getOdometer(),"station",detail.map(d->d.station).orElse(null),"fuelType",detail.map(d->d.fuelType).orElse(null),"paymentMethod",detail.map(d->d.paymentMethod).orElse(null),"reference",detail.map(d->d.transactionReference).orElse(null)));rows.add(r);}}
   case "PREVENTIVE_MAINTENANCE","CORRECTIVE_MAINTENANCE","MAINTENANCE_COST"->{for(var m:maintenance.findAll()){if(m.getArchivedAt()!=null)continue;String maintenanceType=Objects.toString(m.getMaintenanceType(),"").toUpperCase(Locale.ROOT);if(!type.equals("MAINTENANCE_COST")&&!type.startsWith(maintenanceType+"_"))continue;var v=maintenanceVehicle(m);var r=v==null?map("vehicleId",null,"registration",m.getVehicles(),"vehicle","Unmatched legacy reference","date",m.getDate()):base(v,m.getDate());var detail=maintenanceDetails.findByMaintenance_Id(m.getId());r.putAll(map("id",m.getId(),"maintenanceType",m.getMaintenanceType(),"status",m.getStatus(),"costGhs",m.getCost(),"supplier",m.getVendor(),"nextDue",m.getNextDue(),"workOrder",detail.filter(d->d.workOrder!=null).map(d->d.workOrder.reference).orElse(null),"serviceMileage",detail.map(d->d.serviceMileage).orElse(null),"notes",detail.map(d->d.notes).orElse(null)));rows.add(r);}}
   case "ROUTINE_MAINTENANCE"->{for(var inspection:workflows.inspections(null)){var r=base(core.vehicle((Long)inspection.get("vehicleId")),(LocalDate)inspection.get("inspectionDate"));copy(r,inspection,"id","templateName","inspector","outcome","findings","faultId");@SuppressWarnings("unchecked") var checks=(List<Map<String,Object>>)inspection.get("results");if(checks==null||checks.isEmpty())rows.add(r);else for(var check:checks){var detail=new LinkedHashMap<String,Object>(r);detail.put("checklistItem",check.get("label"));detail.put("checkResult",check.get("outcome"));detail.put("checkNotes",check.get("notes"));rows.add(detail);}}}
   case "FAULTS"->{for(var f:workflows.faults(null)){var v=core.vehicle((Long)f.get("vehicleId"));var r=base(v,instantDate(f.get("createdAt")));copy(r,f,"id","reference","category","severity","status","description","location","odometer","reporter","reviewNotes");rows.add(r);}}
   case "PROCUREMENT"->{for(var p:procurement.list(null)){var r=base(core.vehicle((Long)p.get("vehicleId")),(LocalDate)p.get("requestDate"));copy(r,p,"id","reference","category","status","priority","requiredDate","requestedBy","assignedTo","approvedBy","supplier","purchaseReference","estimatedTotal","actualTotal","receivedAt","justification");rows.add(r);}}
   case "FORECASTS"->{for(var c:workflows.components(null)){var r=base(core.vehicle((Long)c.get("vehicleId")),today());copy(r,c,"id","name","category","lastServiceDate","lastServiceMileage","intervalKm","intervalDays","intervalMonths","nextServiceDate","nextServiceMileage");@SuppressWarnings("unchecked") var forecast=(Map<String,Object>)c.get("forecast");r.putAll(forecast);rows.add(r);}}
   case "COMPONENT_REPLACEMENTS"->{for(var order:workflows.workOrders(null))if(Boolean.TRUE.equals(order.get("replacement"))&&"COMPLETED".equals(order.get("status"))){var r=base(core.vehicle((Long)order.get("vehicleId")),(LocalDate)order.get("completedDate"));copy(r,order,"reference","componentNameAtCompletion","completionMileage","partsCost","labourCost","technician","supplier","completionNotes","verifiedAt");rows.add(r);}}
   case "DOCUMENT_EXPIRY"->{for(var v:fleet){var docs=core.documents(v.getId(),false);for(var doc:docs){var r=base(v,(LocalDate)doc.get("expiryDate"));copy(r,doc,"id","documentType","referenceNumber","issueDate","expiryDate","daysRemaining","status","notes");rows.add(r);}if(docs.isEmpty()){legacyExpiry(rows,v,"DVLA",v.getVehicleLicenseExpiry());legacyExpiry(rows,v,"INSURANCE",v.getInsuranceExpiry());}}}
   case "DOWNTIME"->{for(var v:fleet){for(var event:timeline.findByVehicle_IdOrderByCreatedAtDesc(v.getId()))if("VEHICLE_RELEASED".equals(event.eventType)){var r=base(v,event.createdAt.atZone(ZoneId.of("Africa/Accra")).toLocalDate());Long seconds=null;try{var node=json.readTree(event.details);if(node.hasNonNull("recordedDowntimeSeconds"))seconds=node.get("recordedDowntimeSeconds").longValue();}catch(Exception ignored){}r.putAll(map("reference",event.reference,"status","RELEASED","recordedSeconds",seconds,"assessment",event.description));rows.add(r);}profiles.findByVehicle_Id(v.getId()).filter(p->p.downtimeStartedAt!=null).ifPresent(p->{var r=base(v,p.downtimeStartedAt.atZone(ZoneId.of("Africa/Accra")).toLocalDate());r.putAll(map("status",p.operationalStatus,"startedAt",p.downtimeStartedAt,"recordedSeconds",Duration.between(p.downtimeStartedAt,Instant.now()).getSeconds()));rows.add(r);});}}
   case "OPERATING_COST"->rows.addAll(operatingCosts(fleet,from,to));
   default->throw fail(400,"Unsupported report");
  }
  var filtered=rows.stream().filter(r->matches(r,filters)).filter(r->type.equals("OPERATING_COST")||inDate((LocalDate)r.get("date"),from,to)).toList();LinkedHashSet<String> columns=new LinkedHashSet<>();for(var row:filtered)columns.addAll(row.keySet());if(columns.isEmpty())columns.addAll(List.of("registration","vehicle","date"));columns.remove("vehicleId");columns.remove("driverId");return map("type",type,"title",TYPES.get(type),"filters",filters,"generatedAt",Instant.now(),"columns",columns.stream().map(key->map("key",key,"label",label(key))).toList(),"rows",filtered,"total",filtered.size(),"notes","Blank values mean not recorded. Vehicle assignment reports show current assignments; their date is acquisition date, not an invented assignment date. Undated records are excluded when date filters are applied. Operating cost recognizes fuel on purchase dates, procured parts on receipt dates, and remaining maintenance costs on service dates. Received parts are deducted from linked work costs to avoid double counting. Driver filters on vehicle-based reports use current assignments. Totals sum recorded amounts.");
 }
 private void legacyExpiry(List<Map<String,Object>> rows,Vehicles vehicle,String type,LocalDate expiry){if(expiry==null)return;long days=java.time.temporal.ChronoUnit.DAYS.between(today(),expiry);var r=base(vehicle,expiry);r.putAll(map("documentType",type,"expiryDate",expiry,"daysRemaining",days,"status",days<0?"EXPIRED":days==0?"EXPIRES_TODAY":"VALID"));rows.add(r);}
 private List<Map<String,Object>> operatingCosts(List<Vehicles> fleet,LocalDate from,LocalDate to){Map<Long,Map<String,Object>> known=new LinkedHashMap<>();Map<String,Map<String,Object>> unmatched=new LinkedHashMap<>();for(var v:fleet){var row=base(v,null);vehicleFields(row,v);zeroCosts(row);known.put(v.getId(),row);}var purchases=procurement.list(null);Map<Long,BigDecimal> costsInWork=new HashMap<>();for(var purchase:purchases){Long orderId=(Long)purchase.get("workOrderId");for(var receipt:partReceipts.findByRequest_Id((Long)purchase.get("id")))if(orderId!=null)costsInWork.merge(orderId,receipt.quantity.multiply(receipt.unitCost),BigDecimal::add);}
  for(var entry:fuel.findAll())if(entry.getArchivedAt()==null&&inDate(entry.getDate(),from,to)){var v=fuelVehicle(entry);var row=costBucket(v,entry.getVehicle(),known,unmatched);if(row!=null)addCost(row,"fuelCostGhs",money(decimal(entry.getCost())));}
  for(var entry:maintenance.findAll())if(entry.getArchivedAt()==null&&inDate(entry.getDate(),from,to)){var v=maintenanceVehicle(entry);var row=costBucket(v,entry.getVehicles(),known,unmatched);if(row!=null){BigDecimal amount=money(decimal(entry.getCost()));var detail=maintenanceDetails.findByMaintenance_Id(entry.getId());if(detail.isPresent()&&detail.get().workOrder!=null)amount=amount.subtract(costsInWork.getOrDefault(detail.get().workOrder.id,BigDecimal.ZERO));addCost(row,"maintenanceCostGhs",amount);}}
  for(var purchase:purchases){var row=known.get((Long)purchase.get("vehicleId"));if(row!=null)for(var receipt:partReceipts.findByRequest_Id((Long)purchase.get("id")))if(inDate(receipt.receivedDate,from,to))addCost(row,"procurementCostGhs",receipt.quantity.multiply(receipt.unitCost));}
  List<Map<String,Object>> rows=new ArrayList<>(known.values());rows.addAll(unmatched.values());for(var row:rows)row.put("totalCostGhs",((BigDecimal)row.get("fuelCostGhs")).add((BigDecimal)row.get("maintenanceCostGhs")).add((BigDecimal)row.get("procurementCostGhs")));return rows;
 }
 private void zeroCosts(Map<String,Object> row){row.putAll(map("fuelCostGhs",BigDecimal.ZERO,"maintenanceCostGhs",BigDecimal.ZERO,"procurementCostGhs",BigDecimal.ZERO));}
 private Map<String,Object> costBucket(Vehicles vehicle,String legacyReference,Map<Long,Map<String,Object>> known,Map<String,Map<String,Object>> unmatched){if(vehicle!=null)return known.get(vehicle.getId());return unmatched.computeIfAbsent(Objects.toString(legacyReference,"Not Recorded"),key->{var row=map("vehicleId",null,"registration",key,"vehicle","Unmatched legacy reference","date",null);zeroCosts(row);return row;});}
 private void addCost(Map<String,Object> row,String key,BigDecimal amount){row.put(key,((BigDecimal)row.get(key)).add(amount));}
 private static void copy(Map<String,Object> target,Map<String,Object> source,String... keys){for(String key:keys)target.put(key,source.get(key));}
 private static boolean matches(Map<String,Object> row,Map<String,String> filters){for(String key:List.of("vehicleId","driverId","department","project","vehicleType","status")){String value=filters.get(key);if(value!=null&&!value.isBlank()&&!value.equalsIgnoreCase(Objects.toString(row.get(key),"")))return false;}return true;}
 private static boolean inDate(LocalDate date,LocalDate from,LocalDate to){return from==null&&to==null||date!=null&&(from==null||!date.isBefore(from))&&(to==null||!date.isAfter(to));}
 private static LocalDate parseDate(String value){if(value==null||value.isBlank())return null;try{return LocalDate.parse(value);}catch(Exception e){throw fail(400,"Use a valid ISO date filter");}}
 private static LocalDate instantDate(Object value){return value instanceof Instant instant?instant.atZone(ZoneId.of("Africa/Accra")).toLocalDate():null;}
 private static String label(String key){return key.replaceAll("([a-z])([A-Z])","$1 $2").replace("Ghs","(GHS)");}
}
